class Solution:
    def smallestNumber(self, n: int) -> str:
        if n == 1:
            return "1"
        digits = []
        for d in range(9, 1, -1):
            while n % d == 0:
                digits.append(d)
                n //= d
        if n > 1:
            return "-1"
        return ''.join(map(str, sorted(digits)))

c.cpp:
class Solution {
public:
    string smallestNumber(long long n) {
        if (n == 1) return "1";
        vector<int> digits;
        for (int d = 9; d >= 2; --d)
            while (n % d == 0) { digits.push_back(d); n /= d; }
        if (n > 1) return "-1";
        sort(digits.begin(), digits.end());
        string s;
        for (int d : digits) s += char('0' + d);
        return s;
    }
};

c.java:
class Solution {
    public String smallestNumber(long n) {
        if (n == 1) return "1";
        List<Integer> digits = new ArrayList<>();
        for (int d = 9; d >= 2; d--)
            while (n % d == 0) { digits.add(d); n /= d; }
        if (n > 1) return "-1";
        Collections.sort(digits);
        StringBuilder sb = new StringBuilder();
        for (int d : digits) sb.append(d);
        return sb.toString();
    }
}

